let adminMappingId=riderMapping().id;
function adminMapping(){return entityMappings.find(m=>m.enabled&&m.id===adminMappingId)||entityMappings.find(m=>m.enabled)||{id:'',lob:'',entity:'',parameters:[]}}
function adminFields(){return fields.filter(f=>(f.entityMappingId||riderMapping().id)===adminMapping().id)}
function adminTypes(){return configs.map((c,i)=>({c,i})).filter(({c})=>(c.entityMappingId||riderMapping().id)===adminMapping().id)}
function adminContext(){const m=adminMapping(),all=entityMappings.filter(m=>m.enabled);return `<div class="context"><div><label class="label" for="adminLob">Business Line ${info('Choose from all available business lines.')}</label><select id="adminLob">${[...new Set(all.map(x=>x.lob))].map(l=>`<option ${l===m.lob?'selected':''}>${esc(l)}</option>`).join('')}</select></div><div><label class="label" for="adminEntity">Entity ${info('Entities mapped to the selected business line.')}</label><select id="adminEntity">${all.filter(x=>x.lob===m.lob).map(x=>`<option value="${esc(x.id)}" ${x.id===m.id?'selected':''}>${esc(x.entity)}</option>`).join('')}</select></div></div>`}
const beforeAdminContext=context;
context=function(){return role==='admin'?adminContext():beforeAdminContext()};
const beforeAdminRegistry=registry;
registry=function(){const m=adminMapping(),allowed=adminFields();let html=baseTechRegistry().replaceAll('Delivery / Rider',esc(m.lob)+' / '+esc(m.entity));html=html.replace(/<tr><td><strong>[\s\S]*?<button class="link editField" data-index="(\d+)">Open<\/button><\/td><\/tr>/g,(row,i)=>allowed.includes(fields[Number(i)])?row:'');html=html.replace(`Available fields <span class="badge">${fields.length}</span>`,`Available fields <span class="badge">${allowed.length}</span>`);if(!allowed.length)html=html.replace('</tbody>','<tr><td colspan="4" class="empty">No fields registered for this entity.</td></tr></tbody>');return html};
function freshAdminType(){const primary=adminFields()[0]?.id||'';return {name:'',entityMappingId:adminMapping().id,primary,others:[],eligibility:[],entities:adminMapping().parameters.filter(p=>p.included&&p.filter).map(p=>parameterLabel(p.name)),keyFilters:[],payouts:['Lump Sum','Variable'],payout:primary,variableMatrix:['all'],lumpMatrix:['highest','tiered']}}
const beforeAdminConfig=configView;
configView=function(){const m=adminMapping(),allowed=adminFields(),types=adminTypes();if(!allowed.length)return `<div class="titlebar"><h1>Incentive configuration</h1></div>${context()}<section class="panel"><div class="panel-body">Register fields for this entity before creating an incentive type.</div></section>`;if(selected>=0&&!types.some(x=>x.i===selected)){selected=types[0]?.i??-1;draft=selected<0?freshAdminType():structuredClone(configs[selected])}const allFields=fields,allEntityKeys=[...entityKeys];fields=allowed;entityKeys.splice(0,entityKeys.length,...m.parameters.filter(p=>p.included&&p.filter).map(p=>parameterLabel(p.name)));let html;try{html=baseTechConfig()}finally{fields=allFields;entityKeys.splice(0,entityKeys.length,...allEntityKeys)}return html.replace(/<button class="type-tab[^\"]*" data-type="(\d+)">[\s\S]*?<\/button>/g,(button,i)=>types.some(x=>x.i===Number(i))?button:'')};
function changeAdminMapping(id){adminMappingId=id;selected=adminTypes()[0]?.i??-1;draft=selected<0?freshAdminType():structuredClone(configs[selected]);render()}
const beforeAdminBind=bind;
bind=function(){beforeAdminBind();document.getElementById('adminLob')?.addEventListener('change',e=>changeAdminMapping(entityMappings.find(m=>m.enabled&&m.lob===e.target.value)?.id));document.getElementById('adminEntity')?.addEventListener('change',e=>changeAdminMapping(e.target.value));for(const id of ['newType','resetConfig']){const el=document.getElementById(id);if(el){const replacement=el.cloneNode(true);el.replaceWith(replacement);replacement.onclick=()=>{if(id==='newType')selected=-1;draft=selected<0?freshAdminType():structuredClone(configs[selected]);render()}}}};
const beforeAdminSave=saveConfig;
saveConfig=function(){draft.entityMappingId=adminMapping().id;return beforeAdminSave()};
const beforeAdminQuerySave=saveRegistryQuery;
saveRegistryQuery=function(){const ids=new Set(fields.map(f=>f.id));const existing=registryQueryDraft.existingId;const group=registryQueryDraft.groupId;const success=beforeAdminQuerySave();if(success){fields.forEach(f=>{if(!ids.has(f.id)||f.id===existing||f.queryGroup===group)f.entityMappingId=adminMapping().id});render()}return success};
const beforeAdminNav=navRole;
navRole=function(){beforeAdminNav();if(role==='admin'){const m=adminMapping();document.querySelector('.admin').innerHTML=`Admin workspace<small>${esc(m.lob)} · ${esc(m.entity)}</small>`}};
render();
